INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '~2027', 'Universal B2B mandate anticipated (VAT Act, still draft)');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & network', '[["Standard", "EN 16931 (European e-invoice standard)"], ["Core Invoicing Usage Specification", "Peppol BIS Billing 3.0"], ["Network", "Peppol, via a service provider or roaming agreement"], ["Alternative formats", "Permitted by mutual agreement between trading partners"]]', 'Estonia keeps deliberate "format freedom": EN 16931/Peppol is the default, but two parties may agree to something else — there is no single mandated national schema the way France''s Factur-X or Germany''s XRechnung/ZUGFeRD pairing works.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Registration mechanics (B2B buyer-request right)', '[["Where", "Estonian Commercial/Business Register"], ["Who can register", "Any accounting entity wanting to require e-invoices from suppliers"], ["Effect", "Registered status gives the buyer the right to demand an e-invoice; sellers must comply once asked"], ["Legal basis", "Accounting Act amendment, effective 1 July 2025"]]', 'This is the core of Estonia''s "buyer chooses" model — the obligation attaches to the specific buyer''s registration status, not to a blanket rule covering all B2B trade.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s covered today', '[["B2G", "All transfers of goods/services to public sector accounting entities — mandatory since 1 Jul 2019"], ["B2B (buyer-registered)", "Any transaction where the buyer is a registered e-invoice recipient — mandatory on request since 1 Jul 2025"], ["B2B (buyer not registered)", "Entirely voluntary, by mutual agreement"], ["B2C", "Not covered by any e-invoicing rule"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What could change by ~2027', '[["Proposal", "General mandatory B2B e-invoicing for all VAT-registered businesses"], ["Vehicle", "A VAT Act amendment, announced by the Ministry of Finance in December 2024"], ["Status as of Aug 2026", "Draft/proposal stage — no adopted law or confirmed date"], ["Related change proposed", "Removal of the EUR 1,000 per-partner threshold for VAT ledger declarations"]]', 'Treat the ~2027 date as directional, sourced to the European Commission''s own factsheet language ("anticipated by 2027") rather than a confirmed legislative deadline — this is genuinely still a proposal, not enacted law.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No dedicated e-invoicing fine schedule', NULL, NULL, 'Estonia has not legislated a specific fine for failing to honour a registered buyer''s e-invoice request or for B2G non-compliance — these fall under the Accounting Act''s general record-keeping and administrative-offence framework rather than a purpose-built e-invoicing penalty regime, and no confirmed fine figures were found for this page.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔍 The real pressure point is your buyer''s registration status', NULL, NULL, 'Because the B2B obligation is conditional on the buyer''s Business Register status, the practical compliance risk is commercial, not statutory: an unprepared supplier risks friction or lost business with counterparties who have registered as e-invoice recipients, more than a government fine.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your Estonian public-sector invoicing is already compliant', 'If you supply Estonian public bodies, verify you are issuing structured e-invoices — this obligation has applied since July 2019.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Check whether your Estonian counterparties are registered e-invoice recipients', 'A buyer registered in the Business Register as an e-invoice recipient can require you to issue e-invoices — check registration status for your key Estonian trading partners.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up Peppol BIS Billing 3.0 capability', 'Confirm your invoicing software or service provider can issue EN 16931-compliant e-invoices over Peppol — this is the default channel for both the B2G mandate and the B2B buyer-request right.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'EE';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for the VAT Act amendment', 'Monitor Estonia''s Ministry of Finance and Riigikogu for the draft general B2B e-invoicing mandate — if adopted around 2027, it would end the buyer-request model and require e-invoicing for all VAT-registered B2B trade.');
